\node[below left] at (P) {$P$};\node[above] at (R) {$R$};\node[below] at (Q) {$Q$};\node[below] at (S) {$S$};
\node at (1.55,2.25) {$40^{\circ}$};\node at (3.9,0.4) {$110^{\circ}$};
